package analysis

import (
	"fmt"
	"math/big"
	"strconv"
	"strings"
)

// Decimal parses the exact finite decimal representation, including exponent
// notation, without passing through binary float64. A long account number is
// never approximated. Numeric calculations refuse infinite/NaN inputs.
func Decimal(input string) (*big.Rat, bool) {
	s := strings.TrimSpace(input)
	if len(s) == 0 || len(s) > 512 {
		return nil, false
	}
	// Exact intermediate values generated by calculated columns may be rational.
	// Only integer numerator/denominator forms are accepted (not arbitrary maths).
	if strings.Count(s, "/") == 1 {
		parts := strings.SplitN(s, "/", 2)
		n, nok := new(big.Int).SetString(parts[0], 10)
		d, dok := new(big.Int).SetString(parts[1], 10)
		if nok && dok && d.Sign() != 0 {
			return new(big.Rat).SetFrac(n, d), true
		}
		return nil, false
	}
	sign := ""
	if s[0] == '-' || s[0] == '+' {
		if s[0] == '-' {
			sign = "-"
		}
		s = s[1:]
	}
	exponent := 0
	if i := strings.IndexAny(s, "eE"); i >= 0 {
		n, err := strconv.Atoi(s[i+1:])
		if err != nil || n > 308 || n < -308 {
			return nil, false
		}
		exponent = n
		s = s[:i]
	}
	dec := 0
	digits := make([]byte, 0, len(s))
	dot := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '.' && !dot {
			dot = true
			continue
		}
		if c < '0' || c > '9' {
			return nil, false
		}
		digits = append(digits, c)
		if dot {
			dec++
		}
	}
	if len(digits) == 0 {
		return nil, false
	}
	numerator, ok := new(big.Int).SetString(sign+string(digits), 10)
	if !ok {
		return nil, false
	}
	shift := dec - exponent
	if shift < 0 {
		numerator.Mul(numerator, new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(-shift)), nil))
		return new(big.Rat).SetInt(numerator), true
	}
	if shift == 0 {
		return new(big.Rat).SetInt(numerator), true
	}
	denominator := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(shift)), nil)
	return new(big.Rat).SetFrac(numerator, denominator), true
}

func decimalExact(v *big.Rat) string {
	if v == nil {
		return ""
	}
	if v.IsInt() {
		return v.Num().String()
	}
	// If the denominator is a power of 2 and 5 only, represent exactly as a
	// finite decimal. Otherwise retain the exact fraction for traceability.
	d := new(big.Int).Set(v.Denom())
	two, five := 0, 0
	z := big.NewInt(0)
	q := new(big.Int)
	for {
		q.Mod(d, big.NewInt(2))
		if q.Cmp(z) != 0 {
			break
		}
		d.Div(d, big.NewInt(2))
		two++
	}
	for {
		q.Mod(d, big.NewInt(5))
		if q.Cmp(z) != 0 {
			break
		}
		d.Div(d, big.NewInt(5))
		five++
	}
	if d.Cmp(big.NewInt(1)) == 0 && max(two, five) <= 320 {
		out := v.FloatString(max(two, five))
		return strings.TrimRight(strings.TrimRight(out, "0"), ".")
	}
	return v.RatString()
}
func decimalDisplay(v *big.Rat, precision int) string {
	if v == nil {
		return ""
	}
	if precision < 0 || precision > 10 {
		precision = 2
	}
	out := v.FloatString(precision)
	// Normalize the visual -0 after display rounding, never the underlying value.
	if strings.HasPrefix(out, "-") && strings.Trim(out[1:], "0.") == "" {
		out = out[1:]
	}
	if len(out) > 1024 {
		return fmt.Sprintf("%s…", out[:1000])
	}
	return out
}

// ExactDecimalString shares the analysis engine's finite-decimal rendering.
// Non-terminating values retain an exact rational representation.
func ExactDecimalString(value *big.Rat) string { return decimalExact(value) }

// AccountingDecimal is an explicit opt-in parser for imported financial
// exports. Regular Decimal retains its strict grammar (e.g. "1,234" remains
// invalid in formulas) while imported literals may contain thousands groups
// and accounting parentheses. All arithmetic remains exact big.Rat.
func AccountingDecimal(raw string) (*big.Rat, bool) {
	raw = strings.TrimSpace(raw)
	if len(raw) == 0 || len(raw) > 512 {
		return nil, false
	}
	normalized, ok := normalizeAccountingNumber(raw)
	if !ok {
		return nil, false
	}
	return Decimal(normalized)
}

// IsAccountingNumericLiteral rejects identifiers like 0000123 even if the
// string otherwise looks numeric. Do not reformat the user's original text.
func IsAccountingNumericLiteral(raw string) bool {
	_, ok := AccountingNumericValue(raw)
	return ok
}

// AccountingNumericValue combines identifier protection and exact parsing so
// a caller needing the number does not parse each imported literal twice.
func AccountingNumericValue(raw string) (*big.Rat, bool) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil, false
	}
	normalized, ok := normalizeAccountingNumber(raw)
	if !ok {
		return nil, false
	}
	digits := normalized
	if len(digits) > 0 && (digits[0] == '-' || digits[0] == '+') {
		digits = digits[1:]
	}
	if len(digits) > 1 && digits[0] == '0' && digits[1] >= '0' && digits[1] <= '9' {
		return nil, false
	}
	return Decimal(normalized)
}

// normalizeAccountingNumber accepts only genuine 3-digit grouping and
// accounting parentheses; malformed or ambiguous grouping remains text.
func normalizeAccountingNumber(s string) (string, bool) {
	if len(s) > 2 && s[0] == '(' && s[len(s)-1] == ')' {
		s = "-" + strings.TrimSpace(s[1:len(s)-1])
	}
	if !strings.Contains(s, ",") {
		return s, true
	}
	begin := 0
	if s[0] == '-' || s[0] == '+' {
		begin++
	}
	end := len(s)
	if i := strings.IndexAny(s, "eE"); i >= 0 {
		end = i
	}
	if dot := strings.IndexByte(s[:end], '.'); dot >= 0 {
		end = dot
	}
	whole := s[begin:end]
	groups := strings.Split(whole, ",")
	if len(groups) < 2 || len(groups[0]) == 0 || len(groups[0]) > 3 || groups[0] == "0" {
		return "", false
	}
	for i, g := range groups {
		if i > 0 && len(g) != 3 {
			return "", false
		}
		for _, c := range g {
			if c < '0' || c > '9' {
				return "", false
			}
		}
	}
	return s[:begin] + strings.ReplaceAll(whole, ",", "") + s[end:], true
}

// IsNumericLiteral is deliberately conservative for user-edited cells. Textual
// IDs with leading zeros stay text; a user may explicitly convert them with a
// "number" calculated field if numeric arithmetic is intended.
func IsNumericLiteral(raw string) bool {
	s := strings.TrimSpace(raw)
	if len(s) == 0 {
		return false
	}
	if len(s) > 2 && s[0] == '(' && s[len(s)-1] == ')' {
		s = strings.TrimSpace(s[1 : len(s)-1])
	}
	if len(s) == 0 {
		return false
	}
	if s[0] == '-' || s[0] == '+' {
		s = s[1:]
	}
	if len(s) > 1 && s[0] == '0' && s[1] >= '0' && s[1] <= '9' {
		return false
	}
	_, ok := Decimal(raw)
	return ok
}
